import axios from "axios";
import { useloggedUserInfo } from "./stores/UserInfo";

// Central configuration for all service base URLs
const SERVICE_BASE_URLS = {
  main: process.env.VUE_APP_TALYGEN_REPORT_API_URL,
  common: process.env.VUE_APP_COMMON_API,
  hr: process.env.VUE_APP_HR_API_URL,
  asset: process.env.VUE_APP_Asset_API_URL,
  crm: process.env.VUE_APP_CRM_API_URL,
  expense: process.env.VUE_APP_Expense_API_URL,
  // Note: env name kept as-is to avoid breaking existing configuration
  fsm: process.env.Vue_APP_FSM_API,
  approval: process.env.VUE_APP_Approval_API,
  billing: process.env.VUE_APP_BILLINGENGINE_URL,
};

// Safely get auth token from Pinia store
function getAuthToken() {
  try {
    const store = useloggedUserInfo();
    return store && store.GetUserInfo && store.GetUserInfo.Token
      ? store.GetUserInfo.Token
      : null;
  } catch (e) {
    // Swallow errors and treat as unauthenticated
    return null;
  }
}

/**
 * Attach a shared request interceptor to an Axios instance.
 * - Adds Bearer token
 * - Sets sensible default content-type (JSON unless multipart URL)
 * - Keeps Access-Control-Allow-Origin for backward compatibility
 */
function attachAuthInterceptor(instance, options = {}) {
  const {
    multipartOnUrls = ["/ImportContactsPost", "/AddProduct"],
    defaultContentType = "application/json;charset=UTF-8",
  } = options;

  instance.interceptors.request.use(
    (config) => {
      const token = getAuthToken();

      if (token) {
        config.headers = config.headers || {};
        config.headers.Authorization = `Bearer ${token}`;

        const isMultipartUrl =
          config.url && multipartOnUrls.includes(config.url);

        // Only set content-type if not already specified
        if (!config.headers["content-type"]) {
          config.headers["content-type"] = isMultipartUrl
            ? "multipart/form-data"
            : defaultContentType;
        }

        // Normally a server header, but retained to match existing behavior
        config.headers["Access-Control-Allow-Origin"] = "*";
      }

      return config;
    },
    (error) => Promise.reject(error)
  );
}

/**
 * Create an Axios instance with a given baseURL and shared interceptor.
 */
function createAxiosInstance(baseURL, options = {}) {
  const instance = axios.create({ baseURL });
  attachAuthInterceptor(instance, options);
  return instance;
}

// Instantiate all service clients
const instance = createAxiosInstance(SERVICE_BASE_URLS.main);
const instanceCommon = createAxiosInstance(SERVICE_BASE_URLS.common, {
  // Common API is always JSON; do not treat any URL as multipart by default
  multipartOnUrls: [],
});
const instanceHR = createAxiosInstance(SERVICE_BASE_URLS.hr, {
  multipartOnUrls: [],
});
const instanceAsset = createAxiosInstance(SERVICE_BASE_URLS.asset);
const instanceCRM = createAxiosInstance(SERVICE_BASE_URLS.crm);
const instanceExpense = createAxiosInstance(SERVICE_BASE_URLS.expense);
const instanceFsm = createAxiosInstance(SERVICE_BASE_URLS.fsm);
const instanceApproval = createAxiosInstance(SERVICE_BASE_URLS.approval);
const instanceBilling = createAxiosInstance(SERVICE_BASE_URLS.billing);

// Named exports (optional convenience)
export {
  instance,
  instanceCommon,
  instanceHR,
  instanceAsset,
  instanceCRM,
  instanceExpense,
  instanceFsm,
  instanceApproval,
  instanceBilling,
};

// Default export to preserve existing import style
export default {
  instance,
  instanceCommon,
  instanceHR,
  instanceAsset,
  instanceCRM,
  instanceExpense,
  instanceFsm,
  instanceApproval,
  instanceBilling,
};
